package com.greatleyposhley.professy.collaboration;
import org.springframework.stereotype.Service;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.ObjectMapper;import tools.jackson.databind.JsonNode;import tools.jackson.databind.node.ObjectNode;import java.util.*;import static com.greatleyposhley.professy.collaboration.WorkAccess.number;
@Service public class TicketActors {
 private final WorkAccess access;private final WorkspaceAgents agents;private final ObjectMapper json;public TicketActors(WorkAccess access,WorkspaceAgents agents,ObjectMapper json){this.access=access;this.agents=agents;this.json=json;}
 public record Change(String kind,long id,Map<String,Long> assignments){}
 // Negative selection IDs are presentation keys only. Agent IDs never enter human foreign keys.
 public List<Change> prepare(String path,Object body){if(!path.matches("/api/(v1/)?(epics|stories|tasks|issues|testcases)(/(?:[0-9]+|create|bulk-create))?"))return List.of();String[] parts=path.replaceFirst("/api/(v1/)?","").split("/");String kind=access.kind(parts[0]);long id=parts.length>1?number(parts[1]):0;var changes=new ArrayList<Change>();var rows=body instanceof List<?> list?list:Collections.singletonList(body);for(Object value:rows){if(!(value instanceof Map<?,?>))continue;var map=(Map<String,Object>)value;var selections=new LinkedHashMap<String,Long>();for(String role:List.of("assignee","reporter")){var keys=List.of(role+"_user_id",role+"UserId",role+"_id",role+"Id",role);boolean present=false;long selected=0;for(String key:keys)if(map.containsKey(key)){present=true;Object candidate=map.get(key);long n=candidate instanceof Map<?,?> p?number(p.get("id")):number(candidate);selected=n;break;}if(present){selections.put(role,selected);if(selected<0){var agent=agents.row(-selected);if(!"ACTIVE".equals(agent.get("status")))throw new IllegalArgumentException("Select an active agent");for(String key:keys)if(map.containsKey(key))map.put(key,null);}else{for(String key:keys)if(map.containsKey(key))map.put(key,selected==0?null:key.equals(role)?Map.of("id",selected):selected);}}}changes.add(new Change(kind,id>0?id:number(map.get("id")),selections));}return changes;}
 public void finish(List<Change> changes,byte[] response){if(changes.isEmpty())return;JsonNode data=null;try{if(response.length>0)data=json.readTree(response);if(data.has("data"))data=data.get("data");}catch(Exception ignored){}int index=0;for(var change:changes){long id=change.id();if(id==0&&data!=null){JsonNode result=data.isArray()?data.path(index):data;id=result.path("id").asLong(result.path("data").path("id").asLong(0));}index++;if(id<=0||change.assignments().isEmpty())continue;var ticket=access.ticket(change.kind(),id,false);long project=number(ticket.get("work_project_id"));for(var entry:change.assignments().entrySet()){String role=entry.getKey();long selected=entry.getValue();if(selected<0&&!agents.projects(-selected).contains(project))throw new IllegalArgumentException("Add this agent to the ticket's project before assigning it");var previous=access.jdbc.queryForList("SELECT actor_id FROM ticket_actor_assignments WHERE org_id=? AND ticket_type=? AND ticket_id=? AND assignment_role=?",Long.class,access.actor().getOrgId(),change.kind(),id,role.toUpperCase(Locale.ROOT));access.jdbc.update("DELETE FROM ticket_actor_assignments WHERE org_id=? AND ticket_type=? AND ticket_id=? AND assignment_role=?",access.actor().getOrgId(),change.kind(),id,role.toUpperCase(Locale.ROOT));if(change.kind().equals("TEST_CASE")&&role.equals("reporter")){if(selected<0)throw new IllegalArgumentException("Test cases do not have a reporter");continue;}String table=switch(change.kind()){case "EPIC"->"epics";case "STORY"->"stories";case "TASK"->"tasks";case "ISSUE"->"issues";default->"testcases";};String column=change.kind().equals("TEST_CASE")?"user_id":role+"_user_id";access.jdbc.update("UPDATE "+table+" SET "+column+"=? WHERE id=? AND org_id=?",selected>0?selected:null,id,access.actor().getOrgId());if(selected<0){access.jdbc.update("INSERT INTO ticket_actor_assignments(org_id,project_id,ticket_type,ticket_id,assignment_role,actor_id,updated_by) VALUES(?,?,?,?,?,?,?)",access.actor().getOrgId(),project,change.kind(),id,role.toUpperCase(Locale.ROOT),-selected,access.actor().getId());}if(selected<0||!previous.isEmpty()){var before=new LinkedHashMap<String,Object>();var after=new LinkedHashMap<String,Object>();String title=Objects.toString(ticket.get("title"),Objects.toString(ticket.get("name"),change.kind()+"-"+id));before.put("title",title);after.put("title",title);if(!previous.isEmpty())before.put(role+"Agent",agents.row(previous.getFirst()).get("name"));after.put(role+"Agent",selected<0?agents.row(-selected).get("name"):null);if(!Objects.equals(before.get(role+"Agent"),after.get(role+"Agent")))access.jdbc.update("CALL workspace_record_ticket_change(?,?,?,?,?,?,?,?)",access.actor().getOrgId(),project,change.kind(),id,access.actor().getId(),"AGENT_ASSIGNMENT_CHANGED",json.writeValueAsString(before),json.writeValueAsString(after));}access.policy.event(access.actor(),"TICKET_UPDATED",0);}}}
 public void deleted(String path){var matcher=java.util.regex.Pattern.compile("^/api/(?:v1/)?(epics|stories|tasks|issues|testcases)/([0-9]+)$").matcher(path);if(matcher.matches())access.jdbc.update("DELETE FROM ticket_actor_assignments WHERE org_id=? AND ticket_type=? AND ticket_id=?",access.actor().getOrgId(),access.kind(matcher.group(1)),Long.parseLong(matcher.group(2)));}
 public JsonNode enrich(JsonNode data,String kind,Map<String,List<Map<String,Object>>> assignments){if(data.isArray()){for(JsonNode child:data)enrich(child,kind,assignments);return data;}if(!data.isObject())return data;ObjectNode row=(ObjectNode)data;long id=row.path("id").asLong();for(var agent:assignments.getOrDefault(kind+":"+id,List.of())){String role=agent.get("assignment_role").toString().toLowerCase(Locale.ROOT);long key=-number(agent.get("actor_id"));String name=Objects.toString(agent.get("display_name"),"Agent");for(String field:List.of(role+"_user_id",role+"UserId",role+"Id",role+"_id"))row.put(field,key);row.put(role+"Name",name);row.put(role+"_name",name);var person=json.createObjectNode();person.put("id",key);person.put("name",name);person.put("actorType","AGENT");person.put("designation",Objects.toString(agent.get("designation"),"Agent"));row.set(role,person);}for(String field:List.of("items","data","content","results"))if(row.has(field))enrich(row.get(field),kind,assignments);return row;}
 public Map<String,List<Map<String,Object>>> assignments(){var result=new HashMap<String,List<Map<String,Object>>>();for(var row:access.jdbc.queryForList("SELECT t.*,a.display_name,p.designation FROM ticket_actor_assignments t JOIN workspace_actors a ON a.id=t.actor_id JOIN workspace_agent_profiles p ON p.actor_id=a.id WHERE t.org_id=?",access.actor().getOrgId()))result.computeIfAbsent(row.get("ticket_type")+":"+row.get("ticket_id"),k->new ArrayList<>()).add(row);return result;}
}
